// ---- file-scope preamble (translated) ----
// COBJMACROS, NO_SHLWAPI_* : feature-flag defines, no value to carry over.
// WINE_DEFAULT_DEBUG_CHANNEL(shell): debug-channel macro, handled by the DPRINT macros.
// INT WINAPI SHStringFromGUIDA(...): prototype only, provided by the caller's extern block.
// static const IUnknownVtbl threadref_vt: COM vtable, generated by vtbl_gen.py.

#[repr(C)]
pub struct SHLWAPI_THREAD_INFO {
    pub pfnThreadProc: LPTHREAD_START_ROUTINE, /* Thread start */
    pub pfnCallback: LPTHREAD_START_ROUTINE,   /* Thread initialisation */
    pub pData: PVOID,                          /* Application specific data */
    pub bInitCom: BOOL,                        /* Initialise COM for the thread? */
    pub hEvent: HANDLE,                        /* Signal for creator to continue */
    pub refThread: *mut IUnknown,              /* Reference to thread creator */
    pub refIE: *mut IUnknown,                  /* Reference to the IE process */
}
pub type LPSHLWAPI_THREAD_INFO = *mut SHLWAPI_THREAD_INFO;

#[repr(C)]
pub struct threadref {
    pub IUnknown_iface: IUnknown,
    pub ref_: *mut LONG,
}
#[no_mangle]
pub unsafe extern "system" fn CreateAllAccessSecurityAttributes(
    lpAttr: LPSECURITY_ATTRIBUTES,
    lpSec: PSECURITY_DESCRIPTOR,
    p3: DWORD,
) -> LPSECURITY_ATTRIBUTES {
    /* This function is used within SHLWAPI only to create security attributes
     * for shell semaphores. */

    if (GetVersion() & 0x80000000) == 0 {  /* NT */
        if lpSec.is_null() || lpAttr.is_null() {
            return core::ptr::null_mut();
        }

        if InitializeSecurityDescriptor(lpSec, 1) != 0 {
            if SetSecurityDescriptorDacl(lpSec, (TRUE) as BOOL, core::ptr::null_mut(), (FALSE) as BOOL) != 0 {
                (*lpAttr).nLength = core::mem::size_of::<SECURITY_ATTRIBUTES>() as DWORD;
                (*lpAttr).lpSecurityDescriptor = lpSec;
                (*lpAttr).bInheritHandle = (FALSE as i32);
                return lpAttr;
            }
        }
    }
    core::ptr::null_mut()
}

#[no_mangle]
pub unsafe extern "system" fn _SHGetInstanceExplorer(
    lppUnknown: *mut *mut IUnknown,
) -> HRESULT {
    SHGetInstanceExplorer(lppUnknown)
}

unsafe extern "C" fn impl_from_IUnknown(mut iface: *mut IUnknown) -> *mut threadref {
    return (iface as usize).wrapping_sub(core::mem::offset_of!(threadref, IUnknown_iface)) as *mut threadref;
}
unsafe extern "system" fn threadref_QueryInterface(iface: *mut IUnknown, riid: REFIID, ppvObj: *mut LPVOID) -> HRESULT {
    let mut This: *mut threadref = impl_from_IUnknown(iface);

    if ppvObj.is_null() {
        return E_POINTER;
    }

    if IsEqualGUID!(core::ptr::addr_of!(IID_IUnknown), riid) != false {
        *ppvObj = This as LPVOID;
        IUnknown_AddRef(*ppvObj as *mut IUnknown);
        return S_OK;
    }

    *ppvObj = core::ptr::null_mut();
    return E_NOINTERFACE;
}
unsafe extern "system" fn threadref_AddRef(iface: *mut IUnknown) -> ULONG {
    let mut This: *mut threadref = impl_from_IUnknown(iface);

    return InterlockedIncrement((*This).ref_ as *mut i32) as ULONG;
}

unsafe extern "system" fn threadref_Release(mut iface: *mut IUnknown) -> ULONG {
    let mut refcount: LONG = 0;
    let mut This: *mut threadref = impl_from_IUnknown(iface);
    refcount = InterlockedDecrement((*This).ref_ as *mut LONG) as LONG;
    if refcount == 0 {
        HeapFree(GetProcessHeap(), 0 as DWORD, This as PVOID);
    }
    return refcount as ULONG;
}

#[no_mangle]
pub unsafe extern "system" fn SHCreateThreadRef(lprefcount: *mut LONG, lppUnknown: *mut *mut IUnknown) -> HRESULT {
    let mut This: *mut threadref = core::ptr::null_mut();

    if lprefcount.is_null() || lppUnknown.is_null() {
        return E_INVALIDARG;
    }

    This = HeapAlloc(GetProcessHeap(), 0, core::mem::size_of::<threadref>() as SIZE_T) as *mut threadref;
    (*This).IUnknown_iface.lpVtbl = core::ptr::addr_of!(threadref_vt);
    (*This).ref_ = lprefcount;

    *lprefcount = 1;
    *lppUnknown = core::ptr::addr_of_mut!((*This).IUnknown_iface);

    return S_OK;
}

#[no_mangle]
pub unsafe extern "system" fn SHGetThreadRef(lppUnknown: *mut *mut IUnknown) -> HRESULT {
    if SHLWAPI_ThreadRef_index == TLS_OUT_OF_INDEXES {
        return E_NOINTERFACE;
    }
    *lppUnknown = TlsGetValue(SHLWAPI_ThreadRef_index) as *mut IUnknown;
    if (*lppUnknown).is_null() {
        return E_NOINTERFACE;
    }
    /* Add a reference. Caller will Release() us when finished */
    IUnknown_AddRef(*lppUnknown);
    return S_OK;
}

#[no_mangle]
pub unsafe extern "system" fn SHSetThreadRef(lpUnknown: *mut IUnknown) -> HRESULT {
    if SHLWAPI_ThreadRef_index == TLS_OUT_OF_INDEXES {
        return E_NOINTERFACE;
    }

    TlsSetValue(SHLWAPI_ThreadRef_index, lpUnknown as PVOID);
    return S_OK;
}

#[no_mangle]
pub unsafe extern "system" fn SHReleaseThreadRef() -> HRESULT {
    // FIXME("() - stub!\n");
    S_OK
}

unsafe extern "system" fn SHLWAPI_ThreadWrapper(pTi: PVOID) -> DWORD {
    let mut ti: SHLWAPI_THREAD_INFO = core::mem::zeroed();
    let mut hCom: HRESULT = E_FAIL;
    let mut dwRet: DWORD = 0;

    memcpy(
        core::ptr::addr_of_mut!(ti) as *mut c_void,
        pTi as *const c_void,
        core::mem::size_of::<SHLWAPI_THREAD_INFO>() as size_t,
    );

    if ti.bInitCom != 0 {
        hCom = CoInitializeEx(
            core::ptr::null_mut(),
            (COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE) as DWORD,
        );

        if hCom < 0 {
            hCom = CoInitializeEx(
                core::ptr::null_mut(),
                COINIT_DISABLE_OLE1DDE as DWORD,
            );
        }
    }

    if ti.pfnCallback.is_some() {
        ti.pfnCallback.unwrap_unchecked()(ti.pData);
    }

    SetEvent(ti.hEvent);

    dwRet = ti.pfnThreadProc.unwrap_unchecked()(ti.pData);

    if !ti.refThread.is_null() {
        IUnknown_Release(ti.refThread);
    }

    if !ti.refIE.is_null() {
        IUnknown_Release(ti.refIE);
    }

    if hCom >= 0 {
        CoUninitialize();
    }

    return dwRet;
}

#[no_mangle]
pub unsafe extern "system" fn SHCreateThread(
    pfnThreadProc: LPTHREAD_START_ROUTINE,
    pData: *mut core::ffi::c_void,
    dwFlags: DWORD,
    pfnCallback: LPTHREAD_START_ROUTINE,
) -> BOOL {
    let mut ti: SHLWAPI_THREAD_INFO = core::mem::zeroed();
    let mut bCalled: BOOL = (FALSE as i32);

    /* Set up data to pass to the new thread (On our stack) */
    ti.pfnThreadProc = pfnThreadProc;
    ti.pfnCallback = pfnCallback;
    ti.pData = pData as PVOID;
    ti.bInitCom = ((dwFlags & CTF_COINIT) != 0) as BOOL;
    ti.hEvent = CreateEventW(
        core::ptr::null_mut::<_SECURITY_ATTRIBUTES>(),
        (FALSE) as BOOL,
        (FALSE) as BOOL,
        core::ptr::null::<WCHAR>(),
    );

    /* Hold references to the current thread and IE process, if desired */
    if dwFlags & CTF_THREAD_REF != 0 {
        SHGetThreadRef(&raw mut ti.refThread);
    } else {
        ti.refThread = core::ptr::null_mut::<IUnknown>();
    }

    if dwFlags & CTF_PROCESS_REF != 0 {
        _SHGetInstanceExplorer(&raw mut ti.refIE);
    } else {
        ti.refIE = core::ptr::null_mut::<IUnknown>();
    }

    /* Create the thread */
    if !ti.hEvent.is_null() {
        let mut dwRetVal: DWORD = 0;
        let mut hThread: HANDLE = core::ptr::null_mut::<core::ffi::c_void>();

        hThread = CreateThread(
            core::ptr::null_mut::<_SECURITY_ATTRIBUTES>(),
            0,
            Some(SHLWAPI_ThreadWrapper),
            &raw mut ti as PVOID,
            0,
            &raw mut dwRetVal,
        );

        if !hThread.is_null() {
            /* Wait for the thread to signal us to continue */
            WaitForSingleObject(ti.hEvent, INFINITE);
            CloseHandle(hThread);
            bCalled = (TRUE as i32);
        }
        CloseHandle(ti.hEvent);
    }

    if bCalled == 0 {
        if ti.pfnCallback.is_none() && dwFlags & CTF_INSIST != 0 {
            /* Couldn't call, call synchronously */
            (pfnThreadProc.unwrap_unchecked())(pData);
            bCalled = (TRUE as i32);
        } else {
            /* Free references, since thread hasn't run to do so */
            if !ti.refThread.is_null() {
                IUnknown_Release(ti.refThread);
            }

            if !ti.refIE.is_null() {
                IUnknown_Release(ti.refIE);
            }
        }
    }
    return bCalled;
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterGetValue(hSem: HANDLE) -> LONG {
    let mut dwOldCount: LONG = 0;
    ReleaseSemaphore(hSem, 1, core::ptr::addr_of_mut!(dwOldCount)); /* +1 */
    WaitForSingleObject(hSem, 0); /* -1 */
    return dwOldCount;
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterIncrement(hSem: HANDLE) -> LONG {
    let mut dwOldCount: LONG = 0;

    ReleaseSemaphore(hSem, 1, core::ptr::addr_of_mut!(dwOldCount));
    return dwOldCount + 1;
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterDecrement(hSem: HANDLE) -> DWORD {
    let mut dwOldCount: DWORD = 0;

    dwOldCount = SHGlobalCounterGetValue(hSem) as DWORD;
    WaitForSingleObject(hSem, 0);
    return dwOldCount.wrapping_sub(1);
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterCreateNamedW(
    mut lpszName: LPCWSTR,
    mut iInitial: DWORD,
) -> HANDLE {
    static mut szPrefix: [WCHAR; 7] = [0x0073u16, 0x0068, 0x0065, 0x006C, 0x006C, 0x002E, 0x0000];
    let iPrefixLen: ::core::ffi::c_int = 6 as ::core::ffi::c_int;
    let mut szBuff: [WCHAR; (MAX_PATH) as _] = [0; (MAX_PATH) as _];
    let iBuffLen: ::core::ffi::c_int = (::core::mem::size_of::<[WCHAR; (MAX_PATH) as _]>() as usize)
        .wrapping_div(::core::mem::size_of::<WCHAR>() as usize)
        as ::core::ffi::c_int;
    let mut sd: _SECURITY_DESCRIPTOR = core::mem::zeroed();
    let mut sAttr: SECURITY_ATTRIBUTES = core::mem::zeroed();
    let mut pSecAttr: *mut SECURITY_ATTRIBUTES = core::ptr::null_mut::<SECURITY_ATTRIBUTES>();
    let mut hRet: HANDLE = core::ptr::null_mut::<::core::ffi::c_void>();
    WINE_TRACE!("(%s,%d)\n", debugstr_w(lpszName as *const WCHAR), iInitial);
    /* Create Semaphore name */
    memcpy(
        &raw mut szBuff as *mut WCHAR as *mut ::core::ffi::c_void,
        &raw const szPrefix as *const WCHAR as *const ::core::ffi::c_void,
        ((iPrefixLen + 1) as usize)
            .wrapping_mul(::core::mem::size_of::<WCHAR>() as usize),
    );
    if !lpszName.is_null() {
        StrCpyNW(
            (&raw mut szBuff as *mut WCHAR).offset(iPrefixLen as isize),
            lpszName,
            iBuffLen - iPrefixLen,
        );
    }

    /* Initialise security attributes */
    pSecAttr = CreateAllAccessSecurityAttributes(
        &raw mut sAttr,
        &raw mut sd as PSECURITY_DESCRIPTOR,
        0 as DWORD,
    ) as *mut SECURITY_ATTRIBUTES;

    hRet = CreateSemaphoreW(
        pSecAttr as LPSECURITY_ATTRIBUTES,
        iInitial as LONG,
        MAXLONG as LONG,
        &raw mut szBuff as *mut WCHAR as LPCWSTR,
    );
    if hRet.is_null() {
        hRet = OpenSemaphoreW(
            (SYNCHRONIZE | SEMAPHORE_MODIFY_STATE) as DWORD,
            0 as BOOL,
            &raw mut szBuff as *mut WCHAR as LPCWSTR,
        );
    }
    return hRet;
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterCreateNamedA(
    mut lpszName: LPCSTR,
    mut iInitial: DWORD,
) -> HANDLE {
    let mut szBuff: [WCHAR; (MAX_PATH) as _] = [0; (MAX_PATH) as _];
    WINE_TRACE!("(%s,%d)\n", debugstr_a(lpszName as *const ::core::ffi::c_char), iInitial);
    if !lpszName.is_null() {
        MultiByteToWideChar(
            CP_ACP as UINT,
            0 as DWORD,
            lpszName,
            -(1 as ::core::ffi::c_int),
            &raw mut szBuff as LPWSTR,
            (MAX_PATH as i32),
        );
    }
    return SHGlobalCounterCreateNamedW(
        (if !lpszName.is_null() {
            &raw mut szBuff as *mut WCHAR
        } else {
            ::core::ptr::null_mut::<WCHAR>()
        }) as LPCWSTR,
        iInitial,
    );
}

#[no_mangle]
pub unsafe extern "system" fn SHGlobalCounterCreate(guid: REFGUID) -> HANDLE {
    let mut szName: [core::ffi::c_char; 40] = [0; 40];

    /* Create a named semaphore using the GUID string */
    SHStringFromGUIDA(
        guid,
        core::ptr::addr_of_mut!(szName) as LPSTR,
        (core::mem::size_of::<[core::ffi::c_char; 40]>() as usize)
            .wrapping_sub(1 as usize) as INT,
    );
    return SHGlobalCounterCreateNamedA(
        core::ptr::addr_of_mut!(szName) as *mut core::ffi::c_char as LPCSTR,
        0 as DWORD,
    );
}

// COM vtable tables — generated from thread.c by vtbl_gen.py
/// thread.c:178 `static const IUnknownVtbl threadref_vt`  (slot order: com-sys/bindgen_i386.rs)
pub static threadref_vt: IUnknownVtbl = IUnknownVtbl {
    QueryInterface: Some(threadref_QueryInterface),
    AddRef: Some(threadref_AddRef),
    Release: Some(threadref_Release),
};
